import{_ as a,c as t,o as i,ag as r}from"./chunks/framework.C86mscM5.js";const u=JSON.parse('{"title":"事故响应","description":"","frontmatter":{},"headers":[],"relativePath":"devops/security-reliability/incident-response.md","filePath":"devops/security-reliability/incident-response.md","lastUpdated":1788689791000}'),o={name:"devops/security-reliability/incident-response.md"};function l(n,e,s,d,c,h){return i(),t("div",null,e[0]||(e[0]=[r('<h1 id="事故响应" tabindex="-1">事故响应 <a class="header-anchor" href="#事故响应" aria-label="Permalink to &quot;事故响应&quot;">​</a></h1><p>事故响应目标是尽快降低用户影响、恢复服务并从系统层面避免复发，而不是在故障中寻找责任人。</p><h2 id="准备" tabindex="-1">准备 <a class="header-anchor" href="#准备" aria-label="Permalink to &quot;准备&quot;">​</a></h2><ul><li>定义严重等级、值班表、升级路径和状态通知渠道。</li><li>为高风险服务维护 Dashboard、依赖图、回滚步骤和 Runbook。</li><li>部署、配置、功能开关和基础设施变更进入统一时间线。</li><li>定期演练错误发布、Secret 泄漏、仓库不可用和集群故障。</li></ul><h2 id="响应流程" tabindex="-1">响应流程 <a class="header-anchor" href="#响应流程" aria-label="Permalink to &quot;响应流程&quot;">​</a></h2><ol><li><strong>确认</strong>：验证告警、用户影响、范围和当前变更。</li><li><strong>指挥</strong>：指定 Incident Commander、技术处理和沟通角色。</li><li><strong>止损</strong>：回滚、切流、关闭功能、限流或降级，优先恢复核心能力。</li><li><strong>调查</strong>：保留日志、指标、Trace、配置和部署证据，建立时间线。</li><li><strong>恢复</strong>：逐步恢复流量，持续观察 SLI，确认积压任务和数据一致性。</li><li><strong>关闭</strong>：通知相关方，安排复盘并跟踪整改项。</li></ol><h2 id="沟通" tabindex="-1">沟通 <a class="header-anchor" href="#沟通" aria-label="Permalink to &quot;沟通&quot;">​</a></h2><p>内部更新应固定节奏，说明事实、影响、当前动作和下次更新时间。对外状态通知使用用户可理解的影响描述，不发布未经验证的根因。</p><h2 id="复盘" tabindex="-1">复盘 <a class="header-anchor" href="#复盘" aria-label="Permalink to &quot;复盘&quot;">​</a></h2><p>复盘记录影响、发现方式、时间线、根因、促成因素以及哪些防线未生效。整改项必须有负责人、截止时间和验收方式；优先修复能降低同类事故概率或缩短恢复时间的系统性问题。</p><p>Secret 泄漏时先吊销凭据再清理历史；安全事件还需遵循证据保全、合规和通知流程。</p>',11)]))}const _=a(o,[["render",l]]);export{u as __pageData,_ as default};
